"""TLS greeting fetcher with strict certificate chain and hostname verification."""

from __future__ import annotations

import socket
import ssl
from typing import Optional

from tls_client import make_client_context, wrap_client_socket


def fetch_greeting(
    host: str, port: int, cafile: str, server_hostname: Optional[str] = None
) -> bytes:
    """Connect to `host:port` over TLS, verify cert chain + hostname, and return greeting bytes.

    Reads up to and including the first newline (b'\\n'), or until the server closes the
    connection. At most 4096 bytes are read.

    Verification failures raise `ssl.SSLError` (or a subclass like `ssl.CertificateError`).
    """
    if server_hostname is None:
        server_hostname = host

    # Create TCP connection first (ssl wrapping expects a connected socket).
    raw_sock = socket.create_connection((host, port), timeout=10.0)

    # Wrap with TLS using the shared helper that enforces:
    # - cert verification with CA bundle `cafile` (cert_reqs=CERT_REQUIRED)
    # - hostname verification via ssl.match_hostname
    try:
        tls_sock = wrap_client_socket(raw_sock, server_hostname=server_hostname, cafile=cafile)
        try:
            buf = bytearray()
            while len(buf) < 4096:
                chunk = tls_sock.recv(4096 - len(buf))
                if not chunk:
                    break
                buf.extend(chunk)
                nl_index = buf.find(b"\n")
                if nl_index != -1:
                    # Include bytes up to and including the first newline.
                    return bytes(buf[: nl_index + 1])
            return bytes(buf)
        finally:
            try:
                tls_sock.close()
            except Exception:
                pass
    except (ssl.SSLError, ssl.CertificateError):
        # Requirement: verification failures must raise ssl.SSLError (or subclasses).
        raise
    finally:
        # If TLS wrapping failed before we created tls_sock, close raw socket.
        try:
            raw_sock.close()
        except Exception:
            pass
